import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CAKCj7G0.js";const u=JSON.parse('{"title":"React动画（一）","description":"","frontmatter":{},"headers":[],"relativePath":"DuOneClass/09.react/4-7.React动画.md","filePath":"DuOneClass/09.react/4-7.React动画.md"}'),n={name:"DuOneClass/09.react/4-7.React动画.md"};function o(l,e,c,s,p,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="react动画-一" tabindex="-1">React动画（一） <a class="header-anchor" href="#react动画-一" aria-label="Permalink to &quot;React动画（一）&quot;">​</a></h1><p>React动画库：react-transition-group</p><h1 id="react动画-csstransition" tabindex="-1">React动画 - CSSTransition <a class="header-anchor" href="#react动画-csstransition" aria-label="Permalink to &quot;React动画 - CSSTransition&quot;">​</a></h1><p>当进入时，发生：</p><ol><li>为CSSTransition内部的DOM根元素（后续统一称之为DOM元素）添加样式enter</li><li>在一下帧(enter样式已经完全应用到了元素)，立即为该元素添加样式enter-active</li><li>当timeout结束后，去掉之前的样式，添加样式enter-done</li></ol><p>当退出时，发生：</p><ol><li>为CSSTransition内部的DOM根元素（后续统一称之为DOM元素）添加样式exit</li><li>在一下帧(exit样式已经完全应用到了元素)，立即为该元素添加样式exit-active</li><li>当timeout结束后，去掉之前的样式，添加样式exit-done</li></ol><p>设置classNames属性，可以指定类样式的名称</p><ol><li>字符串：为类样式添加前缀</li><li>对象：为每个类样式指定具体的名称（非前缀）</li></ol><p>关于首次渲染时的类样式，appear、apear-active、apear-done，它和enter的唯一区别在于完成时，会同时加入apear-done和enter-done</p><p>还可以与Animate.css联用</p><h1 id="react动画-switchtransition" tabindex="-1">React动画 - SwitchTransition <a class="header-anchor" href="#react动画-switchtransition" aria-label="Permalink to &quot;React动画 - SwitchTransition&quot;">​</a></h1><p>用于有秩序的切换内部组件</p><p>默认情况下：out-in</p><ol><li>当key值改变时，会将之前的DOM根元素添加退出样式（exit,exit-active)</li><li>退出完成后，将该DOM元素移除</li><li>重新渲染内部DOM元素</li><li>为新渲染的DOM根元素添加进入样式(enter, enter-active, enter-done)</li></ol><p>in-out:</p><ol><li>重新渲染内部DOM元素，保留之前的元素</li><li>为新渲染的DOM根元素添加进入样式(enter, enter-active, enter-done)</li><li>将之前的DOM根元素添加退出样式（exit,exit-active)</li><li>退出完成后，将该DOM元素移除</li></ol><blockquote><p>该库寻找dom元素的方式，是使用已经过时的API：findDomNode，该方法可以找到某个组件下的DOM根元素</p></blockquote><h1 id="react动画-transitiongroup" tabindex="-1">React动画 - TransitionGroup <a class="header-anchor" href="#react动画-transitiongroup" aria-label="Permalink to &quot;React动画 - TransitionGroup&quot;">​</a></h1><p>该组件的children，接收多个Transition或CSSTransition组件，该组件用于根据这些子组件的key值，控制他们的进入和退出状态</p>',20)])])}const _=t(n,[["render",o]]);export{u as __pageData,_ as default};
